(async()=>{try{const state=await(await fetch('connection.json')).json();if(!state.enabled){document.getElementById('connection').textContent='Live uploads are not connected yet. The production GitHub repository and Netlify GitHub sign-in must be configured. You can already review replacements and export browser drafts.';return}window.CMS_MANUAL_INIT=true;const script=document.createElement('script');script.src='https://unpkg.com/decap-cms@3.8.4/dist/decap-cms.js';script.onload=async()=>{const config=await(await fetch('config.json')).json();document.getElementById('setup').remove();window.CMS.init({config:{...config,load_config_file:false}})};script.onerror=()=>document.getElementById('connection').textContent='The editor could not load. Please try again.';document.head.append(script)}catch{document.getElementById('connection').textContent='The editing connection could not be checked. Please try again.'}})();
